BEGIN;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE SCHEMA core; CREATE SCHEMA conversation; CREATE SCHEMA assessment; CREATE SCHEMA matching; CREATE SCHEMA audit;
CREATE TYPE conversation.stage AS ENUM ('discovery','measurement','gap_resolution','profile_review','project_matching','complete');
CREATE TYPE conversation.role AS ENUM ('student','assistant','system');
CREATE TYPE assessment.evidence_status AS ENUM ('proposed','accepted','rejected','superseded');
CREATE TYPE assessment.dimension_status AS ENUM ('unknown','provisional','established','contested');
CREATE TYPE assessment.contradiction_status AS ENUM ('open','resolved','dismissed');
CREATE TYPE audit.llm_status AS ENUM ('started','succeeded','failed');
CREATE TABLE core.students(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),external_ref text UNIQUE,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE core.sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),student_id uuid NOT NULL REFERENCES core.students(id),stage conversation.stage NOT NULL DEFAULT 'discovery',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz);
CREATE TABLE conversation.turns(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),session_id uuid NOT NULL REFERENCES core.sessions(id) ON DELETE CASCADE,idempotency_key text NOT NULL,status text NOT NULL CHECK(status IN('processing','completed','failed')),student_message_id uuid,assistant_message_id uuid,created_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz,UNIQUE(session_id,idempotency_key));
CREATE TABLE conversation.messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),session_id uuid NOT NULL REFERENCES core.sessions(id) ON DELETE CASCADE,turn_id uuid REFERENCES conversation.turns(id),sequence integer NOT NULL CHECK(sequence>0),role conversation.role NOT NULL,content text NOT NULL CHECK(length(content)>0),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(session_id,sequence));
ALTER TABLE conversation.turns ADD CONSTRAINT turns_student_message_fk FOREIGN KEY(student_message_id) REFERENCES conversation.messages(id),ADD CONSTRAINT turns_assistant_message_fk FOREIGN KEY(assistant_message_id) REFERENCES conversation.messages(id);
CREATE INDEX messages_session_created_idx ON conversation.messages(session_id,created_at);
CREATE TABLE conversation.memory_snapshots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),session_id uuid NOT NULL REFERENCES core.sessions(id) ON DELETE CASCADE,boundary_sequence integer NOT NULL,content jsonb NOT NULL,prompt_version text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(session_id,boundary_sequence));
CREATE TABLE assessment.dimensions(id smallserial PRIMARY KEY,key text NOT NULL UNIQUE,label text NOT NULL,required boolean NOT NULL DEFAULT false,ordinal smallint NOT NULL UNIQUE);
CREATE TABLE assessment.motivation_values(id smallserial PRIMARY KEY,key text NOT NULL UNIQUE,label text NOT NULL);
CREATE TABLE assessment.question_intents(id smallserial PRIMARY KEY,key text NOT NULL UNIQUE,priority smallint NOT NULL CHECK(priority>0),fallback_template text NOT NULL CHECK(length(fallback_template)>0));
CREATE TABLE assessment.evidence(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),session_id uuid NOT NULL REFERENCES core.sessions(id) ON DELETE CASCADE,dimension_id smallint NOT NULL REFERENCES assessment.dimensions(id),value_key text,strength numeric(4,3) NOT NULL CHECK(strength BETWEEN 0 AND 1),polarity text NOT NULL CHECK(polarity IN('support','oppose')),exact_source_quote text NOT NULL,status assessment.evidence_status NOT NULL,rejection_reason text,reducer_version text,created_at timestamptz NOT NULL DEFAULT now(),CHECK((status='rejected')=(rejection_reason IS NOT NULL)));
CREATE TABLE assessment.evidence_sources(evidence_id uuid NOT NULL REFERENCES assessment.evidence(id) ON DELETE CASCADE,message_id uuid NOT NULL REFERENCES conversation.messages(id),PRIMARY KEY(evidence_id,message_id));
CREATE INDEX evidence_session_dimension_idx ON assessment.evidence(session_id,dimension_id,status);
CREATE TABLE assessment.profile_snapshots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),session_id uuid NOT NULL REFERENCES core.sessions(id) ON DELETE CASCADE,version integer NOT NULL CHECK(version>0),reducer_version text NOT NULL,state jsonb NOT NULL,evidence_boundary timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(session_id,version));
CREATE TABLE assessment.profile_changes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),session_id uuid NOT NULL REFERENCES core.sessions(id) ON DELETE CASCADE,snapshot_id uuid NOT NULL REFERENCES assessment.profile_snapshots(id),dimension_id smallint REFERENCES assessment.dimensions(id),before_state jsonb,after_state jsonb NOT NULL,reason text NOT NULL,accepted_evidence_ids uuid[] NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE assessment.contradictions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),session_id uuid NOT NULL REFERENCES core.sessions(id),dimension_id smallint NOT NULL REFERENCES assessment.dimensions(id),status assessment.contradiction_status NOT NULL DEFAULT 'open',resolution text,resolved_by_evidence_id uuid REFERENCES assessment.evidence(id),created_at timestamptz NOT NULL DEFAULT now(),resolved_at timestamptz,CHECK((status='resolved')=(resolved_at IS NOT NULL)));
CREATE TABLE assessment.contradiction_evidence(contradiction_id uuid REFERENCES assessment.contradictions(id) ON DELETE CASCADE,evidence_id uuid REFERENCES assessment.evidence(id),PRIMARY KEY(contradiction_id,evidence_id));
CREATE INDEX contradictions_open_idx ON assessment.contradictions(session_id) WHERE status='open';
CREATE TABLE assessment.coverage(session_id uuid REFERENCES core.sessions(id) ON DELETE CASCADE,dimension_id smallint REFERENCES assessment.dimensions(id),status assessment.dimension_status NOT NULL DEFAULT 'unknown',updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(session_id,dimension_id));
CREATE TABLE assessment.questions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),session_id uuid NOT NULL REFERENCES core.sessions(id),turn_id uuid NOT NULL REFERENCES conversation.turns(id),intent_id smallint NOT NULL REFERENCES assessment.question_intents(id),target_key text NOT NULL,rationale jsonb NOT NULL,used_fallback boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE matching.project_archetypes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),key text UNIQUE NOT NULL,title text NOT NULL,topics text[] NOT NULL,work_modes text[] NOT NULL,motivations text[] NOT NULL,hard_constraints jsonb NOT NULL DEFAULT '{}',active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE matching.project_fits(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),session_id uuid REFERENCES core.sessions(id),archetype_id uuid REFERENCES matching.project_archetypes(id),profile_snapshot_id uuid REFERENCES assessment.profile_snapshots(id),eligible boolean NOT NULL,topic_score numeric(5,4) NOT NULL,work_mode_score numeric(5,4) NOT NULL,motivation_score numeric(5,4) NOT NULL,total_score numeric(5,4) NOT NULL,failed_constraints text[] NOT NULL DEFAULT '{}',scope_adjustments text[] NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(session_id,archetype_id,profile_snapshot_id));
CREATE TABLE audit.llm_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),session_id uuid REFERENCES core.sessions(id),turn_id uuid REFERENCES conversation.turns(id),purpose text NOT NULL,prompt_version text NOT NULL,deployment_name text NOT NULL,status audit.llm_status NOT NULL,response_id text,input_fingerprint text NOT NULL,usage jsonb,error_code text,created_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz);
CREATE INDEX llm_runs_session_idx ON audit.llm_runs(session_id,created_at);
INSERT INTO assessment.dimensions(key,label,required,ordinal) VALUES ('topics','Topic interests',true,1),('work_mode','Work mode',true,2),('motivation','Motivation',true,3),('capability','Capabilities',false,4),('constraints','Constraints',true,5),('collaboration','Collaboration',false,6),('challenge','Challenge appetite',false,7),('impact','Desired impact',false,8);
INSERT INTO assessment.motivation_values(key,label) VALUES ('mastery','Mastery'),('impact','Impact'),('autonomy','Autonomy'),('recognition','Recognition'),('belonging','Belonging'),('curiosity','Curiosity');
INSERT INTO assessment.question_intents(key,priority,fallback_template) VALUES ('contradiction',1,'I heard two different preferences. Which is closer to what you want now?'),('required_hard_variable',2,'Are there any non-negotiable constraints your project must meet?'),('project_critical_unknown',3,'Which topic would you most like to explore?'),('provisional_dimension',4,'Could you give a concrete example of that preference?'),('project_discrimination',5,'Which of these ways of working sounds more energizing?'),('profile_validation',6,'Does this description of your preferences feel accurate?');
INSERT INTO matching.project_archetypes(key,title,topics,work_modes,motivations,hard_constraints) VALUES ('community_data','Community Data Story',ARRAY['data','community'],ARRAY['analysis','storytelling'],ARRAY['impact','curiosity'],'{}'),('prototype','Rapid Product Prototype',ARRAY['technology','design'],ARRAY['building','iteration'],ARRAY['mastery','autonomy'],'{}'),('field_guide','Research Field Guide',ARRAY['science','environment'],ARRAY['research','writing'],ARRAY['curiosity','impact'],'{}');
COMMIT;
